<style>
:root{--b:#174679;--b2:#0b2a4d;--b3:#2b6cb0;--y:#f6c90e;--bg:#f5f8fd;--l:#dde5f0;--ink:#0b1b2e;--mute:#47607e}
*{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.7 "Segoe UI",system-ui,-apple-system,Roboto,Arial,sans-serif;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}.w{max-width:1100px;margin:0 auto;padding:0 22px}
.ico{width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
.nav{position:sticky;top:0;z-index:50;background:#0b2a4deb;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);color:#fff;border-bottom:1px solid #ffffff1a}
.nv{display:flex;align-items:center;gap:22px;height:62px}
.btn.sm2{padding:8px 16px;font-size:14.5px;border-radius:10px;box-shadow:none}.nav .btn.g{margin-left:auto}.sm2 .ico{width:17px;height:17px}
.skip{position:absolute;left:12px;top:-60px;z-index:99;background:var(--y);color:#10233b;padding:8px 14px;border-radius:8px;font-weight:700}.skip:focus{top:10px}
:focus-visible{outline:3px solid var(--b3);outline-offset:3px;border-radius:6px}
.nav :focus-visible,.hero :focus-visible,.cta :focus-visible,.dc.main:focus-visible,footer :focus-visible{outline-color:var(--y)}
.menu{scroll-margin-top:70px}
.hero{color:#fff;position:relative;overflow:hidden;padding-bottom:110px;background:radial-gradient(900px 480px at 88% 0,#2f74bd55,transparent 65%),linear-gradient(165deg,var(--b2),var(--b))}
.hero:before{content:"";position:absolute;inset:0;background-image:linear-gradient(#ffffff0d 1px,transparent 1px),linear-gradient(90deg,#ffffff0d 1px,transparent 1px);background-size:44px 44px;-webkit-mask:linear-gradient(#000,transparent 85%);mask:linear-gradient(#000,transparent 85%)}
.brand{display:inline-flex;align-items:center;gap:12px;color:#fff}
.brand i{width:46px;height:46px;border-radius:12px;background:#fff;display:grid;place-items:center;padding:5px;flex:none;box-shadow:0 4px 12px #00000026;overflow:hidden}
.brand i svg{width:36px;height:36px;display:block;flex:none}
.bt{display:flex;flex-direction:column;line-height:1.15}.bt b{font-size:19px;font-weight:800;letter-spacing:.8px;color:#fff}
.bt small{font-size:11.5px;font-weight:500;color:#a9c2e2;letter-spacing:.2px;margin-top:3px}
.meteors{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:0}
.meteors i{position:absolute;top:-140px;width:1.5px;border-radius:2px;background:linear-gradient(to bottom,transparent,rgba(255,255,255,.55));opacity:0;transform:translate3d(0,0,0) rotate(35deg);animation:meteor linear infinite;will-change:transform,opacity}
.meteors i:after{content:"";position:absolute;left:50%;bottom:0;width:3px;height:3px;margin-left:-1.5px;border-radius:50%;background:rgba(255,255,255,.7);box-shadow:0 0 6px 1px rgba(255,255,255,.35)}
@keyframes meteor{0%{transform:translate3d(0,0,0) rotate(35deg);opacity:0}8%{opacity:var(--o,.6)}75%{opacity:var(--o,.6)}100%{transform:translate3d(-560px,800px,0) rotate(35deg);opacity:0}}
@media(prefers-reduced-motion:reduce){.meteors{display:none}}
.hg{display:grid;grid-template-columns:1.25fr 1fr;gap:44px;align-items:center;padding:48px 0 0;position:relative}
.tag{display:inline-flex;align-items:center;gap:8px;background:#ffffff18;border:1px solid #ffffff38;border-radius:99px;padding:5px 15px;font-size:13px;font-weight:600}
