h1{font-size:clamp(34px,5.4vw,54px);line-height:1.1;margin:22px 0 18px;font-weight:800;letter-spacing:-.8px;text-wrap:balance}h1 em{font-style:normal;display:inline-block;color:var(--y);background:linear-gradient(110deg,#f6c90e 30%,#ffffff 50%,#f6c90e 70%);background-size:200% auto;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:shineText 3.2s linear infinite}
